CREATE OR REPLACE PROCEDURE sp(para_DNO integer, para_DPhone integer, para_Division text, para_Appt_Type text) LANGUAGE plpgsql AS $$ DECLARE ref_cursor1 CURSOR FOR SELECT * FROM "Minor_in"; ref_cursor2 CURSOR FOR SELECT * FROM "Department"; rec1 RECORD; rec2 RECORD; new_facid integer; BEGIN OPEN ref_cursor1; LOOP FETCH ref_cursor1 INTO rec1; EXIT WHEN NOT FOUND; UPDATE "Minor_in" SET "DNO" = para_DNO WHERE CURRENT OF ref_cursor1; END LOOP; CLOSE ref_cursor1; OPEN ref_cursor2; LOOP FETCH ref_cursor2 INTO rec2; EXIT WHEN NOT FOUND; IF rec2.DPhone = para_DPhone THEN UPDATE "Department" SET "Division" = para_Division WHERE CURRENT OF ref_cursor2; END IF; END LOOP; CLOSE ref_cursor2; SELECT COALESCE(MAX("FacID"), 0) + 1 INTO new_facid FROM "Member_of"; INSERT INTO "Member_of" ("FacID", "Appt_Type") VALUES (new_facid, para_Appt_Type); UPDATE "Member_of" SET "DNO" = para_DNO WHERE "Appt_Type" = para_Appt_Type; END; $$;
